{
  "title": "functions.expression.StringInputSchema",
  "description": "Schema for a string input.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the string.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "enum": {
      "description": "If provided, the string must be one of these values.",
      "anyOf": [
        {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.StringInputSchemaType"
    }
  }
}

{
  "title": "functions.expression.ObjectInputSchema",
  "description": "Schema for an object input with named properties.",
  "type": "object",
  "properties": {
    "description": {
      "description": "Human-readable description of the object.",
      "anyOf": [
        {
          "type": "string"
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "properties": {
      "additionalProperties": {
        "$ref": "functions.expression.InputSchema"
      },
      "description": "Schema for each property in the object.",
      "type": "object"
    },
    "required": {
      "description": "List of property names that must be present.",
      "anyOf": [
        {
          "type": "array",
          "items": {
            "type": "string"
          }
        },
        {
          "type": "null"
        }
      ],
      "omitempty": true
    },
    "type": {
      "$ref": "functions.expression.ObjectInputSchemaType"
    }
  }
}

{
  "title": "functions.expression.Expression",
  "description": "An expression that can be either JMESPath or Starlark.\n\nSerializes as `{\"$jmespath\": \"...\"}` or `{\"$starlark\": \"...\"}` in JSON.\n\n# Examples\n\nJMESPath:\n```json\n{\"$jmespath\": \"input.items[0].name\"}\n```\n\nStarlark:\n```json\n{\"$starlark\": \"input['items'][0]['name']\"}\n```",
  "anyOf": [
    {
      "title": "JMESPath",
      "description": "A JMESPath expression.",
      "type": "object",
      "properties": {
        "$jmespath": {
          "type": "string"
        }
      },
      "additionalProperties": false
    },
    {
      "title": "Starlark",
      "description": "A Starlark expression.",
      "type": "object",
      "properties": {
        "$starlark": {
          "type": "string"
        }
      },
      "additionalProperties": false
    },
    {
      "title": "Special",
      "description": "A predefined special expression variant.",
      "type": "object",
      "properties": {
        "$special": {
          "$ref": "functions.expression.Special"
        }
      },
      "additionalProperties": false
    }
  ]
}
